INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2013, 'Política Internacional', NULL, 'Item 1 (TPS 2013) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2013, 'Português', 'Interpretação de texto', 'Item 2 (TPS 2013): PROVA OBJETIVA (1.ª FASE) Primeira Etapa ADMISSÃO À CARREIRA DE DIPLOMATA LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Ao receber este caderno de prova, confira inicialmente se os seus dados pessoais, transcritos acima, estão corretos e coincidem com o que está registrado na sua folha de respostas. Confira também o seu nome em cada página numerada deste caderno. Em seguida, verifique se ele contém vinte | Quando autorizado pelo chefe de sala, no momento da identificação, escreva, no espaço apropriado da folha de respostas, com a sua caligrafia usual, a seguinte frase: Trabalhe no que você é forte que o resto se fortalece. Conforme previsto em edital, o descumprimento dessa instrução implicará a anulação da sua prova e a sua eliminação do concurso.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2013, 'Português', 'Interpretação de texto', 'Item 3 (TPS 2013): PROVA OBJETIVA (1.ª FASE) Primeira Etapa ADMISSÃO À CARREIRA DE DIPLOMATA LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Ao receber este caderno de prova, confira inicialmente se os seus dados pessoais, transcritos acima, estão corretos e coincidem com o que está registrado na sua folha de respostas. Confira também o seu nome em cada página numerada deste caderno. Em seguida, verifique se ele contém vinte | Você encontrará dois tipos de questões objetivas: múltipla escolha e CERTO ou ERRADO. Nas questões do tipo múltipla escolha, marque, em cada uma, a única opção correta (A, B, C, D ou E), de acordo com o respectivo comando. Nas questões do tipo CERTO ou ERRADO, compostas de quatro itens cada uma, marque, para cada item, o campo designado com o código C, caso julgue o item CERTO, ou o campo designado com o código E, caso julgue o item ERRADO. OBSERVAÇÕES', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2013, 'Português', 'Interpretação de texto', 'Item 4 (TPS 2013): PROVA OBJETIVA (1.ª FASE) Primeira Etapa ADMISSÃO À CARREIRA DE DIPLOMATA LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Ao receber este caderno de prova, confira inicialmente se os seus dados pessoais, transcritos acima, estão corretos e coincidem com o que está registrado na sua folha de respostas. Confira também o seu nome em cada página numerada deste caderno. Em seguida, verifique se ele contém vinte | Recomenda-se que a marcação não seja feita ao acaso: em cada questão do tipo múltipla escolha e em cada item de questão do tipo CERTO ou ERRADO, se a resposta divergir do gabarito oficial definitivo, o candidato receberá pontuação negativa, conforme consta em edital.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2013, 'Português', 'Interpretação de texto', 'Item 5 (TPS 2013): PROVA OBJETIVA (1.ª FASE) Primeira Etapa ADMISSÃO À CARREIRA DE DIPLOMATA LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Ao receber este caderno de prova, confira inicialmente se os seus dados pessoais, transcritos acima, estão corretos e coincidem com o que está registrado na sua folha de respostas. Confira também o seu nome em cada página numerada deste caderno. Em seguida, verifique se ele contém vinte | Não utilize borracha, lápis, lapiseira (grafite) e(ou) qualquer material de consulta que não seja fornecido pelo CESPE/UnB.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2013, 'Português', 'Macroeconomia', 'Item 6 (TPS 2013): PROVA OBJETIVA (1.ª FASE) Primeira Etapa ADMISSÃO À CARREIRA DE DIPLOMATA LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Ao receber este caderno de prova, confira inicialmente se os seus dados pessoais, transcritos acima, estão corretos e coincidem com o que está registrado na sua folha de respostas. Confira também o seu nome em cada página numerada deste caderno. Em seguida, verifique se ele contém vinte | Durante a prova, não se comunique com outros candidatos nem se levante sem autorização de fiscal de sala. 7 8 A duração da primeira etapa da prova objetiva é de duas horas e trinta minutos, já incluído o tempo destinado à identificação-que será feita no decorrer da aplicação e ao preenchimento da folha de respostas. Você deverá permanecer obrigatoriamente em sala por, no minimo, uma hora após o início da prova e poderá levar este caderno de prova somente no decurso dos últimos quinze minutos anteriores ao horário determinado para o término desta etapa da prova. sua folha ', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2013, 'Política Internacional', NULL, 'Item 7 (TPS 2013) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
